<?php declare(strict_types=1);use yii\helpers\Html;use FMonitor2\YiiRuntime\ViewSupport;$id=(int)$calculation['calculationId'];$rev=(int)$calculation['revision'];$oid=(int)$object['objectId'];ViewSupport::begin($this,'Редактор расчёта #'.$id,$identity,'otiz','wide');?><main class="fm2-otiz fm2-otiz-page"><section class="fm2-otiz-surface"><h1><?=$kind==='decision'?'Решение по выплате':'Удержание'?> · <?=Html::encode((string)$object['regnumber'])?></h1><?php if($kind==='decision'):$eid=(string)$recipient['employeeId'];$saved=[];foreach($calculation['decisions']??[]as$d)if(((int)($d['objectId']??0)===$oid||($d['objectId']??null)===null)&&(string)$d['employeeId']===$eid)$saved=$d;$decision=(string)($saved['decision']??$recipient['decision']??'pay');?><form method="post" action="/pilot/otiz/calculations/<?=$id?>/decisions" data-recovery-decision><input type="hidden" name="_csrf" value="<?=Html::encode($csrf)?>"><input type="hidden" name="operationId" value="<?=ViewSupport::uuid()?>"><input type="hidden" name="expectedRevision" value="<?=$rev?>"><input type="hidden" name="objectId" value="<?=$oid?>"><input type="hidden" name="employeeId" value="<?=Html::encode($eid)?>"><p><?=Html::encode((string)$recipient['name'])?></p><fieldset><legend>Решение</legend><label><input type="radio" name="decision" value="pay"<?=$decision==='pay'?' checked':''?>> Платить</label><label><input type="radio" name="decision" value="do_not_pay"<?=$decision==='do_not_pay'?' checked':''?>> Не платить</label></fieldset><label class="shlz-field"><span class="shlz-field__label">Основание решения</span><span class="shlz-field__control"><input class="shlz-input" name="reason" value="<?=Html::encode((string)($saved['reason']??''))?>"></span></label><div class="fm2-otiz-v2-form-actions"><button class="shlz-button shlz-button--secondary" type="submit" formaction="/pilot/otiz/calculations/<?=$id?>/decisions/preview">Предпросмотр</button><button class="shlz-button shlz-button--primary" type="submit">Сохранить решение</button></div></form><?php else:?><form method="post" action="/pilot/otiz/calculations/<?=$id?>/deductions" data-recovery-deduction><input type="hidden" name="_csrf" value="<?=Html::encode($csrf)?>"><input type="hidden" name="operationId" value="<?=ViewSupport::uuid()?>"><input type="hidden" name="expectedRevision" value="<?=$rev?>"><input type="hidden" name="objectId" value="<?=$oid?>"><label class="shlz-field"><span class="shlz-field__label">Вид удержания</span><span class="shlz-field__control"><select class="shlz-input" name="employeeId"><option value="">Общее по объекту</option><?php foreach($calculation['recipients']as$r)if((int)$r['objectId']===$oid):?><option value="<?=Html::encode((string)$r['employeeId'])?>"<?=is_array($recipient)&&(string)$recipient['employeeId']===(string)$r['employeeId']?' selected':''?>>Личное · <?=Html::encode((string)$r['name'])?></option><?php endif?></select></span></label><label class="shlz-field"><span class="shlz-field__label">Сумма удержания</span><span class="shlz-field__control"><input class="shlz-input" name="amount" required></span></label><label class="shlz-field"><span class="shlz-field__label">Причина</span><span class="shlz-field__control"><input class="shlz-input" name="reason" required></span></label><label class="shlz-field"><span class="shlz-field__label">Документ</span><span class="shlz-field__control"><input class="shlz-input" name="document"></span></label><div class="fm2-otiz-v2-form-actions"><button class="shlz-button shlz-button--secondary" type="submit" formaction="/pilot/otiz/calculations/<?=$id?>/deductions/preview">Предпросмотр</button><button class="shlz-button shlz-button--primary" type="submit">Добавить удержание</button></div></form><?php endif?><p><a class="shlz-link" href="/pilot/otiz/calculations/<?=$id?>">Вернуться к расчёту</a></p></section></main><?php ViewSupport::end($this);?>
